// 状态管理
let currentCategory = "all";
let presenterActive = false;
let presenterIndex = 0;
let presenterList = [];
let teleprompterFontSize = 1.4; // rem
let hoveredCompanyId = null;

// DOM 元素
const matrixGrid = document.getElementById("matrix-grid");
const companyCount = document.getElementById("company-count");
const searchInput = document.getElementById("search-input");
const tabButtons = document.querySelectorAll(".filter-tabs .tab-btn");
const btnPresenterMode = document.getElementById("btn-presenter-mode");
const btnGridView = document.getElementById("btn-grid-view");
const btnImageView = document.getElementById("btn-image-view");
const gridViewSection = document.getElementById("grid-view-section");
const imageInteractiveView = document.getElementById("image-interactive-view");
const mapHitboxOverlay = document.getElementById("map-hitbox-overlay");

const detailModal = document.getElementById("detail-modal");
const modalClose = document.getElementById("modal-close");
const modalLogo = document.getElementById("modal-logo");
const modalCompanyName = document.getElementById("modal-company-name");
const modalCompanyCategory = document.getElementById("modal-company-category");
const modalTech = document.getElementById("modal-tech");
const modalDescription = document.getElementById("modal-description");
const modalWebsiteLink = document.getElementById("modal-website-link");

const presenterOverlay = document.getElementById("presenter-overlay");
const teleprompterText = document.getElementById("teleprompter-text");
const scriptPhaseTitle = document.getElementById("script-phase-title");
const stageCard = document.getElementById("stage-card");
const btnPrev = document.getElementById("btn-prev");
const btnNext = document.getElementById("btn-next");
const btnExitPresenter = document.getElementById("btn-exit-presenter");
const btnFontInc = document.getElementById("btn-font-inc");
const btnFontDec = document.getElementById("btn-font-dec");

// ==========================================================================
// 渲染主网格
// ==========================================================================
function renderGrid(filteredCompanies) {
  matrixGrid.innerHTML = "";
  
  if (filteredCompanies.length === 0) {
    matrixGrid.innerHTML = `<div class="glass" style="grid-column: 1/-1; padding: 40px; text-align: center; color: var(--text-muted);">未找到符合条件的合作伙伴 🔍</div>`;
    companyCount.textContent = 0;
    return;
  }
  
  filteredCompanies.forEach(company => {
    const card = document.createElement("div");
    card.className = "company-card glass";
    card.setAttribute("data-id", company.id);
    card.setAttribute("data-category", company.category);
    
    // 渲染卡片内容，增加 card-link-btn
    card.innerHTML = `
      <button class="card-link-btn" title="访问官方网站" onclick="event.stopPropagation(); window.open('${company.website}', '_blank');">
        <svg viewBox="0 0 24 24"><path d="M19 19H5V5h7V3H5c-1.11 0-2 .9-2 2v14c0 1.1.89 2 2 2h14c1.1 0 2-.9 2-2v-7h-2v7zM14 3v2h3.59l-9.83 9.83 1.41 1.41L19 6.41V10h2V3h-7z"/></svg>
      </button>
      <div class="logo-container">
        <img src="logos/${company.logo || ''}" onerror="this.style.display='none'; this.nextElementSibling.style.display='flex';" class="logo-img">
        <div class="logo-icon-box" style="display: none;">${company.shortName}</div>
      </div>
      <h3>${company.name}</h3>
      <span class="tech-tag">${getShortTechName(company.tech)}</span>
    `;
    
    // 点击打开详情弹窗
    card.addEventListener("click", () => openDetailModal(company));
    
    // 双击直接在新页面中打开公司官网
    card.addEventListener("dblclick", () => {
      window.open(company.website, '_blank');
    });
    
    matrixGrid.appendChild(card);
  });
  
  companyCount.textContent = filteredCompanies.length;
}

// 辅助方法：缩短展示的生态关键词
function getShortTechName(tech) {
  return tech.split(" / ")[0];
}

function cleanPartnerPosition(company) {
  const raw = company.disassembly || "";
  const marker = "主营业务与产业定位：";
  const markerIndex = raw.indexOf(marker);
  let position = markerIndex >= 0 ? raw.slice(markerIndex + marker.length) : raw;
  position = position
    .replace(/^英稳达合作伙伴生态链第\s*\d+\s*行(?:补充)?成员。?/, "")
    .replace(/访问官方网站.*$/, "")
    .trim();

  if (!position || position.length > 110 || /别再以为|兄弟|韭菜|搞钱|收割/.test(position)) {
    position = company.tech && !company.tech.startsWith("www.google.com/search")
      ? `${company.tech} 对应的 NVIDIA 生态参与方`
      : "NVIDIA 生态墙中的待确认参与方";
  }

  return position.replace(/[。；;]+$/, "");
}

function isEasterEgg(company) {
  return /【.*彩蛋】/.test(company.name || "") ||
    ["hua_niang", "fruit_lady", "wang_ji", "fu_ba_wang", "zhuan_yao", "ai_you_de_gou", "shengni"].includes(company.id);
}

function inferNvidiaRelation(company, position) {
  const text = `${company.name} ${company.tech} ${position}`.toLowerCase();

  if (isEasterEgg(company)) {
    return "这不是技术伙伴，更像是墙面里的叙事彩蛋：把黄仁勋在台湾的公开行程、宴请场景和科技圈社交记忆放进同一张图，给硬核供应链叙事加一个可传播的生活切口。";
  }

  if (/tsmc|sk hynix|micron|samsung|asic|semiconductor|chip|hbm|guc|alchip|synopsys|cadence|arm/.test(text)) {
    return "它更接近 NVIDIA 的底层供应链或芯片设计生态：先进制程、内存、EDA、IP 或 ASIC 能力，决定 AI GPU 与加速系统能不能持续迭代和量产。";
  }

  if (/server|data center|datacenter|cloud|compute|gpu|supermicro|quanta|wiwynn|wistron|foxconn|gigabyte|asus|hpe|dell|lenovo|qct/.test(text)) {
    return "它可能承担 AI 算力落地环节：把 NVIDIA GPU、网络与机柜系统做成可部署的数据中心、服务器、工作站或云服务。";
  }

  if (/robot|isaac|automotive|vehicle|driving|adas|unitree|agility|figure|agibot|1x/.test(text)) {
    return "它代表 NVIDIA 在机器人和物理 AI 方向的应用层伙伴：训练、仿真、感知和推理可能会用到 GPU、Isaac、Omniverse 或 Jetson 生态。";
  }

  if (/security|network|firewall|zero trust|palo alto|zscaler|fortinet|checkpoint|akamai|cloudflare|cisco/.test(text)) {
    return "它对应 AI 数据中心的网络与安全侧：当 GPU 集群变成关键基础设施，流量调度、零信任、防护和可观测性都会成为 NVIDIA 生态的外围刚需。";
  }

  if (/university|college|edu|gov|hospital|medical|research|hpc|nchc|harvard|stanford|ntu|nthu|nycu/.test(text)) {
    return "它更像研究、人才或行业应用节点：通过高性能计算、AI 医疗、科研平台和教育资源，把 NVIDIA 的算力平台带进真实研究场景。";
  }

  if (/model|ai|llm|software|platform|simulation|design|omniverse|adobe|openai|anthropic|runway|deepl/.test(text)) {
    return "它代表应用和软件层：模型训练、推理、生成式 AI、仿真或设计工作流，都可能依赖 NVIDIA GPU、CUDA 或企业 AI 软件栈。";
  }

  return "它出现在这面墙上，至少说明它被放进 NVIDIA 的合作伙伴叙事里。具体关系可能是硬件适配、软件优化、行业方案、渠道合作或共同客户场景，需要结合官网和发布会材料继续确认。";
}

function buildPresenterScript(item) {
  return item.script || item.description || "";
}

// ==========================================================================
// 搜索和过滤逻辑
// ==========================================================================
function handleFilter() {
  const query = searchInput.value.toLowerCase().trim();
  
  const filtered = companies.filter(company => {
    const matchCategory = currentCategory === "all" || company.category === currentCategory;
    const matchSearch = company.name.toLowerCase().includes(query) || 
                        company.tech.toLowerCase().includes(query) ||
                        (company.description && company.description.toLowerCase().includes(query));
    return matchCategory && matchSearch;
  });
  
  renderGrid(filtered);
  updateImageMapFilter(filtered);
}

// ==========================================================================
// 详情弹窗逻辑
// ==========================================================================
function openDetailModal(company) {
  if (company.logo) {
    modalLogo.innerHTML = `
      <img src="logos/${company.logo}" onerror="this.style.display='none'; this.nextElementSibling.style.display='flex';" class="logo-img" style="max-height:80%; max-width:80%; object-fit:contain;">
      <span style="display:none; font-family:var(--font-family-title); font-weight:800; font-size:1.8rem; color:var(--color-nvidia);">${company.shortName}</span>
    `;
  } else {
    modalLogo.textContent = company.shortName;
  }
  
  // 使 Logo 也可以点击跳转官网
  modalLogo.style.cursor = "pointer";
  modalLogo.title = "点击访问官方网站";
  modalLogo.onclick = () => {
    window.open(company.website, '_blank');
  };
  
  modalCompanyName.textContent = company.name;
  modalCompanyCategory.textContent = getCategoryName(company.category);
  
  // 移除之前的类别样式并添加新的
  modalCompanyCategory.className = "badge badge-" + company.category;
  
  // 设置官网链接
  if (modalWebsiteLink) {
    modalWebsiteLink.href = company.website;
  }
  
  modalTech.textContent = getShortTechName(company.tech);
  modalDescription.textContent = company.description || "";
  
  detailModal.classList.add("active");
}

function getCategoryName(cat) {
  if (cat && cat.startsWith("row-")) {
    return "第 " + cat.split("-")[1] + " 行合作伙伴";
  }
  switch(cat) {
    case "hardware": return "硬核硬件组 (RTX Spark)";
    case "software": return "生产力软件组 (OpenShell)";
    case "industrial": return "具身智能与工业孪生 (Omniverse)";
    default: return "英伟达生态伙伴";
  }
}

// 关闭弹窗
modalClose.addEventListener("click", () => {
  detailModal.classList.remove("active");
});

// 点击弹窗背景关闭
detailModal.addEventListener("click", (e) => {
  if (e.target === detailModal) {
    detailModal.classList.remove("active");
  }
});

// ==========================================================================
// 演示提词器模式逻辑
// ==========================================================================
function enterPresenterMode() {
  presenterActive = true;
  presenterOverlay.classList.remove("hidden");
  document.body.style.overflow = "hidden"; // 锁屏滚动
  
  // 根据当前过滤器，构建演示队列
  const phaseInfo = studyScriptPhases[currentCategory];
  scriptPhaseTitle.textContent = phaseInfo.title;
  
  presenterList = [];
  
  // 1. 添加开头介绍脚本段落
  if (currentCategory === "all" || (studyScriptPhases.all && studyScriptPhases.all.scripts)) {
    studyScriptPhases.all.scripts.forEach((scriptText, idx) => {
      presenterList.push({
        type: "intro",
        title: "开场介绍",
        shortName: "📢",
        category: currentCategory,
        tech: "NVIDIA Computex 2026",
        description: "本部分为演示的开场概述，旨在为观众介绍合作伙伴大屏幕的产业链背景与技术分类。",
        script: scriptText
      });
    });
  }
  
  // 2. 添加具体的公司演示段落
  let targetCompanyIds = [];
  if (phaseInfo && phaseInfo.companies) {
    targetCompanyIds = phaseInfo.companies;
  } else {
    const filteredIds = companies.filter(c => c.category === currentCategory).map(c => c.id);
    targetCompanyIds = filteredIds.length ? filteredIds : companies.map(c => c.id);
  }
  
  targetCompanyIds.forEach(id => {
    const comp = companies.find(c => c.id === id);
    if (comp) {
      presenterList.push({
        type: "company",
        ...comp
      });
    }
  });
  
  // 3. 添加结尾收尾引导
  if (phaseInfo.outro) {
    presenterList.push({
      type: "outro",
      title: "章节收尾",
      shortName: "✓",
      category: currentCategory,
      tech: "本行生态关系复盘",
      description: "本部分为章节的收尾总结，总结该行企业在整个英伟达计算产业集群中的协作角色。",
      script: phaseInfo.outro
    });
  }
  
  presenterIndex = 0;
  updatePresenterStage();
}

function updatePresenterStage() {
  if (presenterList.length === 0) return;
  const currentItem = presenterList[presenterIndex];
  
  // 1. 渲染右侧展示卡片
  stageCard.setAttribute("data-category", currentItem.category || "all");
  const logoHtml = currentItem.logo ? `
    <img src="logos/${currentItem.logo}" onerror="this.style.display='none'; this.nextElementSibling.style.display='flex';" class="logo-img" style="max-height:80%; max-width:80%; object-fit:contain;">
    <span style="display:none;">${currentItem.shortName || currentItem.name.charAt(0)}</span>
  ` : `<span>${currentItem.shortName || currentItem.name.charAt(0)}</span>`;

  const isCompany = currentItem.type === "company" || currentItem.website;
  const websiteBtnHtml = isCompany ? `
    <a href="${currentItem.website}" target="_blank" class="btn btn-secondary btn-sm presenter-website-btn" style="padding: 2px 8px; font-size: 0.75rem; border-radius: 4px; display: inline-flex; align-items: center; gap: 4px; border-color: rgba(255,255,255,0.15);" onclick="event.stopPropagation();">
      <span>官网</span>
      <svg style="width: 10px; height: 10px; fill: currentColor;" viewBox="0 0 24 24"><path d="M19 19H5V5h7V3H5c-1.11 0-2 .9-2 2v14c0 1.1.89 2 2 2h14c1.1 0 2-.9 2-2v-7h-2v7zM14 3v2h3.59l-9.83 9.83 1.41 1.41L19 6.41V10h2V3h-7z"/></svg>
    </a>
  ` : '';

  const logoClickAttr = isCompany ? `style="cursor: pointer;" title="点击访问官方网站" onclick="window.open('${currentItem.website}', '_blank')"` : '';

  stageCard.innerHTML = `
    <div class="stage-header">
      <div class="stage-logo" ${logoClickAttr}>${logoHtml}</div>
      <div>
        <h2>${currentItem.name || currentItem.title}</h2>
        <div class="stage-meta">
          <span class="badge badge-${currentItem.category || 'hardware'}">${getCategoryName(currentItem.category || 'all')}</span>
          <span class="tech-badge">${getShortTechName(currentItem.tech)}</span>
          ${websiteBtnHtml}
        </div>
      </div>
    </div>
    <div class="stage-body">
      <div class="info-block info-glow">
        <h3>企业简介与生态定位</h3>
        <p>${currentItem.description || ""}</p>
      </div>
    </div>
  `;
  
  // 2. 渲染左侧提词器文本
  teleprompterText.innerHTML = "";
  presenterList.forEach((item, idx) => {
    const p = document.createElement("p");
    p.textContent = `[${idx + 1}/${presenterList.length}] ${buildPresenterScript(item)}`;
    if (idx === presenterIndex) {
      p.className = "active-script";
    }
    teleprompterText.appendChild(p);
  });
  
  // 自动滚动到当前活动提词段落
  const activeParagraph = teleprompterText.querySelector(".active-script");
  if (activeParagraph) {
    activeParagraph.scrollIntoView({ behavior: "smooth", block: "center" });
  }
  
  // 按钮禁用状态控制
  btnPrev.disabled = presenterIndex === 0;
  btnNext.innerHTML = presenterIndex === presenterList.length - 1 ? '完成演示 (Esc)' : '下一家 (→) <svg class="icon" viewBox="0 0 24 24"><path d="M10 6L8.59 7.41 13.17 12l-4.58 4.59L10 18l6-6z"/></svg>';
}

function exitPresenterMode() {
  presenterActive = false;
  presenterOverlay.classList.add("hidden");
  document.body.style.overflow = "auto";
}

// 演示导航
btnNext.addEventListener("click", () => {
  if (presenterIndex < presenterList.length - 1) {
    presenterIndex++;
    updatePresenterStage();
  } else {
    exitPresenterMode();
  }
});

btnPrev.addEventListener("click", () => {
  if (presenterIndex > 0) {
    presenterIndex--;
    updatePresenterStage();
  }
});

btnExitPresenter.addEventListener("click", exitPresenterMode);

// 键盘控制（左右方向键和 Esc 键）
document.addEventListener("keydown", (e) => {
  if (!presenterActive) return;
  if (e.key === "ArrowRight") {
    btnNext.click();
  } else if (e.key === "ArrowLeft") {
    btnPrev.click();
  } else if (e.key === "Escape") {
    exitPresenterMode();
  }
});

// 提词器字号缩放
btnFontInc.addEventListener("click", () => {
  teleprompterFontSize += 0.1;
  teleprompterText.style.fontSize = teleprompterFontSize + "rem";
});

btnFontDec.addEventListener("click", () => {
  if (teleprompterFontSize > 1) {
    teleprompterFontSize -= 0.1;
    teleprompterText.style.fontSize = teleprompterFontSize + "rem";
  }
});

// ==========================================================================
// 大图交互渲染与状态同步
// ==========================================================================
function renderImageMap() {
  if (!mapHitboxOverlay) return;
  mapHitboxOverlay.innerHTML = "";
  
  companies.forEach(company => {
    if (!company.coords) return;
    
    const hitbox = document.createElement("div");
    hitbox.className = "map-hitbox";
    hitbox.setAttribute("data-id", company.id);
    
    // Percentage conversion based on original image size (3024 x 1232)
    const x1 = company.coords.x1;
    const x2 = company.coords.x2;
    const y1 = company.coords.y1;
    const y2 = company.coords.y2;
    
    const left = (x1 / 3024) * 100;
    const top = (y1 / 1232) * 100;
    const width = ((x2 - x1) / 3024) * 100;
    const height = ((y2 - y1) / 1232) * 100;
    
    hitbox.style.left = `${left}%`;
    hitbox.style.top = `${top}%`;
    hitbox.style.width = `${width}%`;
    hitbox.style.height = `${height}%`;
    
    hitbox.title = company.name;
    
    // Single click: open modal
    hitbox.addEventListener("click", (e) => {
      e.stopPropagation();
      openDetailModal(company);
    });
    
    // Double click: open website
    hitbox.addEventListener("dblclick", (e) => {
      e.stopPropagation();
      window.open(company.website, '_blank');
    });
    
    // Hover: dynamically add/remove highlight in SVG mask overlay for quick visual response
    hitbox.addEventListener("mouseenter", () => {
      hoveredCompanyId = company.id;
      const darkOverlayRect = document.getElementById("dark-overlay-rect");
      if (darkOverlayRect && darkOverlayRect.style.opacity === "1") {
        const query = searchInput.value.toLowerCase().trim();
        const filtered = companies.filter(c => {
          const matchCategory = currentCategory === "all" || c.category === currentCategory;
          const matchSearch = c.name.toLowerCase().includes(query) || 
                              c.tech.toLowerCase().includes(query) ||
                              (c.description && c.description.toLowerCase().includes(query));
          return matchCategory && matchSearch;
        });
        updateImageMapFilter(filtered);
      }
    });
    
    hitbox.addEventListener("mouseleave", () => {
      hoveredCompanyId = null;
      const darkOverlayRect = document.getElementById("dark-overlay-rect");
      if (darkOverlayRect && darkOverlayRect.style.opacity === "1") {
        const query = searchInput.value.toLowerCase().trim();
        const filtered = companies.filter(c => {
          const matchCategory = currentCategory === "all" || c.category === currentCategory;
          const matchSearch = c.name.toLowerCase().includes(query) || 
                              c.tech.toLowerCase().includes(query) ||
                              (c.description && c.description.toLowerCase().includes(query));
          return matchCategory && matchSearch;
        });
        updateImageMapFilter(filtered);
      }
    });
    
    mapHitboxOverlay.appendChild(hitbox);
  });
}

function updateImageMapFilter(filteredCompanies) {
  const hitboxes = document.querySelectorAll(".map-hitbox");
  if (hitboxes.length === 0) return;
  
  const filteredIds = new Set(filteredCompanies.map(c => c.id));
  
  // 1. Update hitboxes' filtered-out class to disable interactions for unselected ones
  hitboxes.forEach(hitbox => {
    const companyId = hitbox.getAttribute("data-id");
    if (filteredIds.has(companyId)) {
      hitbox.classList.remove("filtered-out");
    } else {
      hitbox.classList.add("filtered-out");
    }
  });

  // 2. Update SVG mask overlay
  const darkOverlayRect = document.getElementById("dark-overlay-rect");
  const maskHoles = document.getElementById("mask-holes");
  if (!darkOverlayRect || !maskHoles) return;

  const query = searchInput.value.toLowerCase().trim();
  if (currentCategory === "all" && !query) {
    // Show full screen brightly: hide dark overlay
    darkOverlayRect.style.opacity = "0";
    maskHoles.innerHTML = "";
  } else {
    // Dim the screen and cut bright window holes for filtered items and hovered item
    darkOverlayRect.style.opacity = "1";
    
    let holesHtml = "";
    filteredCompanies.forEach(company => {
      if (company.coords && !company.id.startsWith("taiwan_mesh_")) {
        const x1 = company.coords.x1;
        const x2 = company.coords.x2;
        const y1 = company.coords.y1;
        const y2 = company.coords.y2;
        const w = x2 - x1;
        const h = y2 - y1;
        holesHtml += `<rect x="${x1}" y="${y1}" width="${w}" height="${h}" rx="4" ry="4" fill="black" />`;
      }
    });
    
    // Also cut a hole for the hovered item, if any, even if it is filtered out
    if (hoveredCompanyId) {
      const company = companies.find(c => c.id === hoveredCompanyId);
      if (company && company.coords && !filteredIds.has(hoveredCompanyId)) {
        const x1 = company.coords.x1;
        const x2 = company.coords.x2;
        const y1 = company.coords.y1;
        const y2 = company.coords.y2;
        const w = x2 - x1;
        const h = y2 - y1;
        holesHtml += `<rect x="${x1}" y="${y1}" width="${w}" height="${h}" rx="4" ry="4" fill="black" />`;
      }
    }
    
    maskHoles.innerHTML = holesHtml;
  }
}

// ==========================================================================
// 初始化绑定
// ==========================================================================

// 视图切换绑定
if (btnGridView && btnImageView && gridViewSection && imageInteractiveView) {
  btnGridView.addEventListener("click", () => {
    btnGridView.classList.add("active");
    btnImageView.classList.remove("active");
    gridViewSection.classList.remove("hidden");
    imageInteractiveView.classList.add("hidden");
  });
  
  btnImageView.addEventListener("click", () => {
    btnImageView.classList.add("active");
    btnGridView.classList.remove("active");
    imageInteractiveView.classList.remove("hidden");
    gridViewSection.classList.add("hidden");
  });
}

// 搜索栏监听
searchInput.addEventListener("input", handleFilter);

// 分类 Tabs 监听
tabButtons.forEach(button => {
  button.addEventListener("click", () => {
    tabButtons.forEach(btn => btn.classList.remove("active"));
    button.classList.add("active");
    currentCategory = button.getAttribute("data-category");
    handleFilter();
  });
});

// 开启演示模式
btnPresenterMode.addEventListener("click", enterPresenterMode);

// 初次渲染全部数据
document.addEventListener("DOMContentLoaded", () => {
  renderGrid(companies);
  renderImageMap();
  handleFilter(); // Synchronize initially
});






















